From 9db7595a83420f029dd52a462d766d4ac585e9c7 Mon Sep 17 00:00:00 2001
From: Holger Schemel <info@artsoft.org>
Date: Thu, 7 Feb 2019 23:40:30 +0100
Subject: [PATCH] fixed bug when snapping envelope (introduced by commit
 931d95b5)


diff --git a/src/events.c b/src/events.c
index 31d45abf..ee5e492c 100644
--- a/src/events.c
+++ b/src/events.c
@@ -405,7 +405,10 @@ void ClearPlayerAction(void)
   // simulate key release events for still pressed keys
   key_joystick_mapping = 0;
   for (i = 0; i < MAX_PLAYERS; i++)
+  {
     stored_player[i].action = 0;
+    stored_player[i].snap_action = 0;
+  }

   ClearJoystickState();
   ClearPlayerMouseAction();
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by the failure to reset the `snap_action` for each player when clearing player actions, which could lead to unintended behavior in the envelope snapping functionality. This oversight meant that previous snap actions could persist, affecting the current state and operations of the players.

        Commit message:
        fixed bug when snapping envelope (introduced by commit
 931d95b5)  

        Patch:

 void ClearPlayerAction(void)
 {
   int i;

   // simulate key release events for still pressed keys
   key_joystick_mapping = 0;
   for (i = 0; i < MAX_PLAYERS; i++)
+  {
     stored_player[i].action = 0;
+    stored_player[i].snap_action = 0;
+  }

   ClearJoystickState();
   ClearPlayerMouseAction();
 }



